import {summary,finished,finite,quantile,groups,comparable} from './analytics.js';
import {esc,time,pace,empty,table,tr,info,sexHistogram,finishPlaceScatter,bands,statusLabel,lines,horizontalBars,finishProgression} from './charts.js';
export const methodText={
 finish:'Publicerade positiva sluttider för fullföljare (FINISHED) i aktuellt filtrerat urval. Median är mittenvärdet (medelvärdet av de två mittersta vid jämnt antal). Histogrammets fasta intervall anges per loppfamilj. Saknad tid räknas inte som noll. Ingen prestationsjämförelse över banbyten görs här.',
 segment:'Beräknat från verkliga passager vid explicita analysgränser. Samma kompletta fullföljarkohort används genom samtliga delsträckor. Startens tid 0 är beräknad. Median kräver n ≥ 5, Q25–Q75 n ≥ 10 och Q10–Q90 n ≥ 20. Fart använder källans rapporterade distanser; dessa är inte GPX-mätningar. Saknad passage fylls inte. Plats ± använder publicerade placeringar; positivt är vunna platser. Brutet lopp (DNF) avser sista observerade gräns, inte verifierad brytplats.',
 history:'Deltagande kan visas över banbyten. Median och bästa tid visas endast mot uttryckligen jämförbara upplagor i samma familj med verifierad banversion (CourseVersion) eller jämförelsegrupp. Inställda år är luckor. Historiken avser hela upplagor och påverkas inte av fältfiltren. Ingen personkoppling görs mellan år.',
 replay:'Beräknad position, inte individuell GPS. Tiden interpoleras linjärt mellan verkliga timingankare på aktuell upplagas lokala rutt. Starttid 0 är ett modellankare. Brutet lopp (DNF) stannar vid sista publicerade passage. Checkpointplatsen är projicerad från dokumenterat geografiskt ankare; den exakta tidtagningsmattan är inte verifierad. Arrangörens markering på tävlingsdagen gäller framför GPX.'
};
export function methodGuide(a=null,rows=null,state=null,boot=null){
 const active=state?Object.entries(state.filters||{}).filter(([,value])=>value):[],family=a&&boot?.presentation?.[a.race.race_family]?.label,filterName={sex:'Kön',class_name:a?.race?.participant?.entity==='team'?'Lagklass':'Klass',status:'Status',club:'Klubb / ort'};
 const filterValue=(key,value)=>key==='sex'?(value==='F'?'Kvinnor':value==='M'?'Män':value):key==='status'?statusLabel(value):value;
 const context=a&&rows&&state?'<div class="method-context"><div><span>Aktivt lopp</span><strong>'+esc((family||a.race.race_family)+' · '+a.race.year)+'</strong></div><div><span>Dataskop</span><strong>Vald upplaga + historiksammanställning</strong></div><div><span>Aktuellt urval</span><strong>'+rows.length+' / '+a.records.length+' resultat</strong></div><div><span>Filter</span><strong>'+esc(active.length?active.map(([key,value])=>(filterName[key]||key)+': '+filterValue(key,value)).join(' · '):'Inga fältfilter')+'</strong></div></div>':'';
 return '<div class="card method-guide"><div class="card-heading"><div><p class="eyebrow">LÄS DATA RÄTT</p><h3>Så läser du analysen</h3></div><span class="badge">Fyra principer</span></div><div class="method-grid"><div><span>01</span><h3>KÄLLVÄRDE</h3><p>Publicerade resultat, status och passager från Sportstiming.</p></div><div><span>02</span><h3>BERÄKNAT</h3><p>Median, fart och interpolation. Saknade observationer förblir saknade.</p></div><div><span>03</span><h3>JÄMFÖRBART</h3><p>Prestation över år kräver uttryckligt verifierade banor.</p></div><div><span>04</span><h3>AKTUELLT URVAL</h3><p>Fältanalyser följer filtren ovan. Sökning, profiler och valda jämförelser är fristående.</p></div></div>'+context+'</div>';
}
export function kpis(rows,race,unit){
 const s=summary(rows),rate=s.starters?s.dnf/s.starters*100:null;
 return '<div class="kpis">'+[['Startande',s.starters,s.unknown?s.unknown+' med okänd status utanför antal startande':'Källstödd startstatus'],['Fullföljde',s.finished,'av '+s.total+' publicerade resultat'],['Mediantid',time(s.median),pace(s.median/race.nominal_distance_km,unit)+' · nominell distans'],['DNF',s.dnf,rate===null?'–':rate.toFixed(1).replace('.',',')+' % av startande']].map(([a,b,c])=>'<div class="kpi"><span>'+a+'</span><strong>'+b+'</strong><small>'+c+'</small></div>').join('')+'</div>';
}
function groupTable(rows,field,unit,race,{limit=Infinity,label='grupper'}={}){
 const g=groups(rows,field);if(!g.length)return empty('Publicerade uppgifter saknas för detta urval.');
 const heads=['Grupp','Resultat','Fullföljde','Median','Medianfart'],row=x=>tr([esc(x.name),x.total,x.finished,time(x.median),pace(finite(x.median)?x.median/race.nominal_distance_km:null,unit)]);
 const visible=g.slice(0,limit),rest=g.slice(limit),primary=table(heads,visible.map(row));
 return primary+(rest.length?'<details class="group-details"><summary>Visa ytterligare '+rest.length+' '+esc(label)+'</summary>'+table(heads,rest.map(row))+'</details>':'');
}
function percentileValue(values,p){
 const n=values.length,required=p===50?5:(p===25||p===75?10:20);
 return n>=required?quantile(values,p/100):null;
}
function groupVisual(rows,field,unit,race,label,{filterable=false,limit=8}={}){
 const all=groups(rows,field);if(!all.length)return empty('Publicerade uppgifter saknas för detta urval.');
 const top=all.slice(0,limit),max=Math.max(1,...top.map(g=>g.total));
 const bars=top.map(g=>{const inner='<span title="'+esc(g.name)+'">'+esc(g.name)+'</span><div class="group-bar-track"><i style="width:'+Math.max(2,100*g.total/max).toFixed(1)+'%"></i></div><strong>'+g.total+'</strong><small>'+g.finished+' i mål · median '+time(g.median)+'</small>';return filterable?'<button type="button" class="group-bar-row group-bar-button" data-quick-filter="'+esc(field)+'" data-quick-value="'+esc(g.name)+'" title="Filtrera analysen på '+esc(g.name)+'">'+inner+'</button>':'<div class="group-bar-row">'+inner+'</div>';}).join('');
 return '<div class="group-bars" role="list" aria-label="'+esc(label||'Grupper')+'">'+bars+'</div><details class="group-details"><summary>Visa detaljerad gruppstatistik ('+all.length+')</summary>'+groupTable(rows,field,unit,race)+'</details><p class="chart-caption">Staplar visar publicerade resultat. Median visas endast när gruppen har minst fem fullföljare.'+(filterable?' Klicka en stapel för att filtrera hela analysen.':'')+'</p>';
}
function ageDistribution(rows){
 const values=rows.filter(r=>finite(r.age)).map(r=>Number(r.age));if(values.length<5)return empty('För få publicerade exakta åldrar för en fördelning.');
 const min=Math.floor(Math.min(...values)/5)*5,max=Math.ceil((Math.max(...values)+1)/5)*5,bins=[];
 for(let from=min;from<max;from+=5){const to=from+4,count=values.filter(v=>v>=from&&v<from+5).length;bins.push({from,to,count});}
 const peak=Math.max(1,...bins.map(b=>b.count));
 return '<div class="age-bars" aria-label="Åldersfördelning">'+bins.map(b=>'<div class="age-bar"><span>'+b.from+'–'+b.to+'</span><div><i style="height:'+Math.max(4,100*b.count/peak).toFixed(1)+'%"></i></div><strong>'+b.count+'</strong></div>').join('')+'</div>';
}
function groupSegmentComparison(a,rows,field,label,state){
 if(!a.race.capabilities.segment_analysis)return '';
 const ranked=groups(rows,field).filter(g=>g.finished>=5).slice(0,4);if(ranked.length<2)return '';
 const series=ranked.map(g=>({name:g.name,stats:a.segmentStats(g.rows)})),format=x=>finite(x?.median)?pace(x.median,state.unit):time(x?.time?.median),hasAnyPace=series.some(s=>s.stats.some(x=>finite(x.median)));
 return '<section class="card wide group-segment"><div class="card-heading"><div><p class="eyebrow">GRUPPJÄMFÖRELSE</p><h3>'+esc(label)+' genom loppet</h3></div><div class="heading-tools"><span class="badge">Topp '+ranked.length+' efter antal resultat</span>'+info('group-segment-'+field,'De största grupperna med minst fem fullföljare jämförs delsträcka för delsträcka. Medianfart används där segmentdistans finns; annars mediantid.')+'</div></div>'+table(['Delsträcka',...series.map(s=>esc(s.name))],a.boundary.slice(1).map((cp,i)=>tr([esc(a.boundary[i].name+' → '+cp.name),...series.map(s=>format(s.stats[i]))])))+'<p class="chart-caption">'+(hasAnyPace?'Medianfart visas där rapporterad distans finns; annars används mediantid.':'Mediantid visas eftersom rapporterad segmentdistans saknas.')+' Gruppvärden kräver minst fem kompletta observationer genom analysgränserna.</p></section>';
}
const sexName=s=>s==='F'?'Kvinnor':'Män';
function genderCards(rows){
 const known=rows.filter(r=>r.sex==='F'||r.sex==='M');if(!known.length)return '';
 const both=known.some(r=>r.sex==='F')&&known.some(r=>r.sex==='M'),controls=both?'<div class="series-controls" aria-label="Visa könsperspektiv"><label><input type="checkbox" data-series-toggle="female" checked> <i class="female"></i>Kvinnor</label><label><input type="checkbox" data-series-toggle="male" checked> <i class="male"></i>Män</label></div>':'';return '<div class="interactive-chart gender-interactive">'+controls+'<div class="gender-kpis">'+['F','M'].map(s=>{const group=known.filter(r=>r.sex===s),starters=group.filter(r=>['FINISHED','DNF','DSQ'].includes(r.status)),finish=group.filter(finished),rate=starters.length?finish.length/starters.length*100:null,key=s==='F'?'female':'male';return '<article data-series="'+key+'" class="'+(s==='F'?'female':'male')+'"><span>'+sexName(s)+'</span><strong>'+starters.length+'</strong><small>startande · '+finish.length+' fullföljde · median '+time(finish.length>=5?quantile(finish.map(r=>r.finish_seconds),.5):null)+(rate===null?'':' · '+rate.toFixed(0)+' % i mål')+'</small></article>';}).join('')+'</div><p class="coverage-note">Könstäckning '+known.length+' av '+rows.length+' publicerade resultat. Startantal exkluderar DNS och okänd status; saknade uppgifter ingår inte i könsserierna.</p></div>';
}
export function progressionBySex(rows,split){
 const finishedRows=rows.filter(finished),women=finishedRows.filter(r=>r.sex==='F'),men=finishedRows.filter(r=>r.sex==='M');
 if(!finishedRows.length)return empty('Inga fullföljare i urvalet.');
 const controls=split?'<div class="series-controls" aria-label="Visa percentilserier"><label><input type="checkbox" data-series-toggle="female" checked> <i class="female"></i>Kvinnor</label><label><input type="checkbox" data-series-toggle="male" checked> <i class="male"></i>Män</label></div>':'';
 const levels=[10,25,50,75,90].map(p=>{const threshold=percentileValue(finishedRows.map(r=>r.finish_seconds),p),count=g=>finite(threshold)?g.filter(r=>r.finish_seconds<=threshold).length:0,bar=(label,key,g)=>{const n=count(g),share=g.length?100*n/g.length:0,own=percentileValue(g.map(r=>r.finish_seconds),p);return '<div class="percentile-sex-row" data-series="'+key+'"><span>'+label+'</span><div class="percentile-sex-track"><i style="width:'+share.toFixed(1)+'%"></i></div><strong>'+n+' / '+g.length+'</strong><small>Egen P'+p+': '+time(own)+'</small></div>';};return '<article class="percentile-level"><header><strong>P'+p+'</strong><small>'+(p===50?'Median':'Fältgräns')+'</small><b>'+time(threshold)+'</b></header><div class="percentile-sex-bars">'+(split?bar('Kvinnor','female',women)+bar('Män','male',men):'<div class="percentile-total-row"><span>Fullföljare vid eller före gränsen</span><strong>'+count(finishedRows)+' / '+finishedRows.length+'</strong></div>')+'</div></article>';}).join('');
 return '<div class="interactive-chart percentile-interactive">'+controls+'<div class="percentile-board">'+levels+'</div></div><p class="chart-caption">P10–P90 är sluttidströsklar för hela urvalet. Staplarna visar hur många kvinnor respektive män som gått i mål senast vid den gemensamma tröskeln; egen percentiltid visas som jämförelse. Median kräver n ≥ 5, P25/P75 n ≥ 10 och P10/P90 n ≥ 20.</p>';
}

function fieldFlow(a,rows,state){
 if(!a.race.capabilities.segment_analysis||a.boundary.length<2)return '';
 const starters=rows.filter(r=>['FINISHED','DNF','DSQ'].includes(r.status));if(!starters.length)return '';
 const total=starters.length,showSex=a.race.capabilities.sex_filter&&a.race.participant.entity==='person'&&!state?.filters?.sex;
 const items=a.boundary.filter(cp=>cp.key!=='start').map(cp=>{const observed=starters.map(r=>({r,o:a.observation(r,cp.key)})).filter(x=>x.o),times=observed.map(x=>x.o.elapsed_seconds).filter(finite),places=observed.map(x=>x.o.place_overall).filter(finite),pct=100*observed.length/total,w=observed.filter(x=>x.r.sex==='F').length,m=observed.filter(x=>x.r.sex==='M').length;
  return '<article><div class="field-flow-head"><strong>'+esc(cp.name)+'</strong><span>'+observed.length+' / '+total+' · '+pct.toFixed(0)+' %</span></div><div class="field-flow-track"><span style="width:'+pct.toFixed(1)+'%"></span></div><small>Median passage '+time(times.length>=5?quantile(times,.5):null)+(places.length>=5?' · medianplats '+Math.round(quantile(places,.5)):'')+(showSex?' · kvinnor '+w+' · män '+m:'')+'</small></article>';});
 return '<section class="card field-flow-card"><div class="card-heading"><div><p class="eyebrow">FÄLTFLÖDE</p><h3>Så långt når startfältet</h3></div><div class="heading-tools"><span class="badge">Verkliga passager</span>'+info('field-flow-method','Andelen bygger endast på publicerade passager bland faktiska startande. Startpunkten 100 % utelämnas eftersom den inte tillför analys. DNF stannar vid sista observerade kontroll.')+'</div></div><div class="field-flow-list">'+items.join('')+'</div><p class="chart-caption">Fält kvar bygger endast på publicerade passager. DNF placeras aldrig längre än sista observerade kontroll.</p></section>';
}
function genderDnfLocations(a,rows){
 if(!a.race.capabilities.segment_analysis||a.race.participant.entity!=='person')return '';
 const dnf=rows.filter(r=>r.status==='DNF'&&(r.sex==='F'||r.sex==='M'));if(!dnf.length)return '';
 const entries=a.checkpoints.filter(cp=>cp.key!=='start'&&cp.key!=='finish').map(cp=>{const women=dnf.filter(r=>r.sex==='F'&&a.passages(r).at(-1)?.checkpoint===cp.key).length,men=dnf.filter(r=>r.sex==='M'&&a.passages(r).at(-1)?.checkpoint===cp.key).length;return {cp,women,men,total:women+men};}).filter(x=>x.total);
 if(!entries.length)return '';
 return '<section class="card dnf-location-card"><div class="card-heading"><div><p class="eyebrow">DNF</p><h3>Sista observerade kontroll</h3></div>'+info('dnf-location-method','Visar sista publicerade passage för DNF med källstödd könsuppgift. Detta är en observationsgräns, inte en verifierad exakt brytplats.')+'</div>'+table(['Kontroll','Kvinnor','Män','Totalt'],entries.map(x=>tr([esc(x.cp.source_label||x.cp.name),x.women,x.men,x.total])))+'<p class="chart-caption">Kvinnor och män separeras endast från källstödda uppgifter.</p></section>';
}
function strongestFinish(a,rows,state){
 if(!a.race.capabilities.segment_analysis||a.boundary.length<2)return '';
 const index=a.boundary.length-2,field=Math.max(1,summary(a.records).starters),label=a.race.participant.entity==='team'?'Lag':'Namn',segment=esc(a.boundary[index].name+' → '+a.boundary[index+1].name);
 const rank=input=>input.map(r=>{const s=finished(r)?a.segment(r,index):null;return s&&finite(s.gain)&&s.gain>0?{r,gain:s.gain,score:100*s.gain/field}:null;}).filter(Boolean).sort((x,y)=>y.score-x.score||y.gain-x.gain).slice(0,5);
 const render=input=>{const ranked=rank(input);return ranked.length?table([label,'Vunna platser','Relativt startfält'],ranked.map(x=>tr([esc(x.r.name),'+'+x.gain,x.score.toFixed(1).replace('.',',')+' %']))):empty('Ingen källstödd positiv placeringsförändring i gruppen.');};
 const split=a.race.participant.entity==='person'&&!state?.filters?.sex&&rows.some(r=>r.sex==='F')&&rows.some(r=>r.sex==='M');
 const body=split?'<div class="finish-sex-grid"><div><h4><span class="sex-F">Kvinnor</span></h4>'+render(rows.filter(r=>r.sex==='F'))+'</div><div><h4><span class="sex-M">Män</span></h4>'+render(rows.filter(r=>r.sex==='M'))+'</div></div>':render(rows);
 return '<section class="card wide"><div class="card-heading"><div><p class="eyebrow">AVSLUTNING</p><h3>Starkast avslutning</h3><p class="muted">'+segment+'</p></div><div class="heading-tools"><span class="badge">Placeringslyft</span>'+info('finish-strength-method','Visar fullföljare som vunnit flest placeringar på den sista publicerade delsträckan. Resultatet normaliseras mot hela upplagans faktiska startfält.')+'</div></div>'+body+'<p class="chart-caption">Vunna placeringar normaliseras mot hela upplagans faktiska startfält. Kvinnor och män visas separat när källstödet räcker. Endast publicerade placeringar vid båda segmentändarna används.</p></section>';
}
function starterSexCoverageOK(e){return e?.starters>0&&e.starter_sex_coverage>=20&&e.starter_sex_coverage/e.starters>=.8;}
function historyFingerprint(a,entries,boot){
 const current=entries.find(e=>e.race_key===a.race.race_key);if(!current)return '';
 const perf=entries.filter(e=>e.year<current.year&&comparable(a.race,e,boot.courses)&&finite(e.median));
 const other=entries.filter(e=>e.year<current.year&&e.records>0),cards=[];
 if(perf.length>=2&&finite(current.median)){const base=quantile(perf.map(e=>e.median),.5);cards.push(['Mediantidsindex',100*current.median/base,'100 = jämförbar historisk normalnivå · högre betyder längre mediantid']);}
 const dnfRefs=perf.filter(e=>e.starters>0).map(e=>e.dnf/e.starters).filter(finite),currentDnf=current.starters>0?current.dnf/current.starters:null;
 if(dnfRefs.length>=2&&finite(currentDnf)&&quantile(dnfRefs,.5)>0)cards.push(['DNF-andel',100*currentDnf/quantile(dnfRefs,.5),'100 = jämförbar historisk normalnivå · högre betyder större DNF-andel']);
 const starterRefs=other.filter(e=>e.starters>0);if(starterRefs.length>=2&&current.starters>0){const base=quantile(starterRefs.map(e=>e.starters),.5);if(base>0)cards.push(['Startfält',100*current.starters/base,'100 = medianen för tidigare genomförda år i samma loppfamilj']);}
 const sexRefs=other.filter(starterSexCoverageOK),currentShare=starterSexCoverageOK(current)?current.women_starters/current.starter_sex_coverage:null,shares=sexRefs.map(e=>e.women_starters/e.starter_sex_coverage);
 if(shares.length>=2&&finite(currentShare)&&quantile(shares,.5)>0)cards.push(['Kvinnorepresentation',100*currentShare/quantile(shares,.5),'100 = medianen för tidigare år med minst 80 % könstäckning bland faktiska startande']);
 if(!cards.length)return empty('För få jämförbara historiska år för ett stabilt årsindex. Historiska råvärden visas fortfarande nedan.');
 return '<section class="card wide history-fingerprint"><div class="card-heading"><div><p class="eyebrow">ÅRETS FINGERAVTRYCK</p><h3>Valt år mot sin historiska referens</h3></div><div class="heading-tools"><span class="badge">Index 100</span>'+info('history-fingerprint-method','Index 100 är medianen för tidigare tillåtna referensår. Prestationsmått använder endast uttryckligen jämförbara banor; deltagandemått kan spänna över banversioner.')+'</div></div><div class="fingerprint-grid">'+cards.map(([name,value,note])=>'<article><span>'+name+'</span><strong>'+value.toFixed(0)+'</strong><small>'+note+'</small></article>').join('')+'</div><p class="chart-caption">Prestationsindex använder endast uttryckligen jämförbara upplagor och kräver minst två andra referensår. Deltagandemått kan spänna över banversioner. Indexen är deskriptiva, inte kausala.</p></section>';
}
function historyRecord(a,entries,boot){
 const pool=entries.filter(e=>e.race_key===a.race.race_key||comparable(a.race,e,boot.courses)).filter(e=>finite(e.best));if(!pool.length)return '';
 const best=pool.slice().sort((x,y)=>x.best-y.best)[0];
 return '<section class="card history-record"><div class="card-heading"><div><p class="eyebrow">JÄMFÖRBAR TOPPNOTERING</p><h3>'+time(best.best)+'</h3></div>'+info('history-record-method','Snabbaste publicerade tid inom vald upplagas uttryckligen verifierade jämförbarhetsserie. Det är inte ett officiellt banrekord utanför den serien.')+'</div><p><strong>'+esc(best.best_name||'Publicerat resultat')+'</strong> · '+best.year+(best.best_bib?' · #'+esc(best.best_bib):'')+'</p><p class="chart-caption">Snabbaste publicerade tid inom vald upplagas verifierade whole-course-jämförbarhet. Detta är inte ett påstående om rekord utanför den serien.</p></section>';
}
function historySex(entries){
 const rows=entries.filter(starterSexCoverageOK).sort((a,b)=>a.year-b.year);if(!rows.length)return '';
 return '<section class="card history-sex"><div class="card-heading"><div><p class="eyebrow">KÖN ÖVER TID</p><h3>Kvinnor och män i startfältet</h3></div><div class="heading-tools"><span class="badge">≥ 80 % täckning</span>'+info('history-sex-method','Historiska könsserier visas endast för år där minst 80 % av de faktiska startande har källstödd könsuppgift. Saknade år blir luckor, aldrig nollor.')+'</div></div>'+table(['År','Kvinnor start','Män start','Kvinnor i mål','Män i mål','Andel kvinnor','Täckning'],rows.map(e=>{const wr=e.women_starters?100*e.women_finished/e.women_starters:null,mr=e.men_starters?100*e.men_finished/e.men_starters:null;return tr([e.year,e.women_starters,e.men_starters,e.women_finished+(finite(wr)?' · '+wr.toFixed(1).replace('.',',')+' %':''),e.men_finished+(finite(mr)?' · '+mr.toFixed(1).replace('.',',')+' %':''),(100*e.women_starters/e.starter_sex_coverage).toFixed(1).replace('.',',')+' %',e.starter_sex_coverage+'/'+e.starters]);}))+'<p class="chart-caption">Endast källstödda könsuppgifter bland faktiska startande. Procentsiffran efter antal i mål är fullföljandegrad inom respektive kön. År med låg täckning utelämnas i stället för att tolkas som noll.</p></section>';
}
export function overview(a,rows,state,boot){
 const f=rows.filter(finished),step=boot.presentation[a.race.race_family].bin_seconds,showSex=a.race.capabilities.sex_filter&&a.race.participant.entity==='person'&&!state.filters.sex&&rows.some(r=>r.sex==='F')&&rows.some(r=>r.sex==='M');
 const classCard='<section class="card '+(showSex?'overview-class-card':'wide')+'"><div class="card-heading"><div><p class="eyebrow">STARTFÄLTET</p><h3>'+ (a.race.participant.entity==='team'?'Lagklasser':'Klasser')+'</h3></div>'+info('class-method','Grupper kommer från publicerad klass. Full tabell är valfri; median kräver minst fem fullföljare.')+'</div>'+groupVisual(rows,'class_name',state.unit,a.race,a.race.participant.entity==='team'?'Lagklasser':'Klasser',{filterable:true,limit:6})+'<p class="chart-caption">Källans klasser. Gruppmedian kräver fem fullföljare.</p></section>';
 return '<section class="view-intro"><p class="eyebrow">ÖVERSIKT · AKTUELLT URVAL</p><h2>Läs loppet uppifrån och ned</h2><p>Nyckeltal, målgångar, könsserier och klasser inleder det sammanhängande analysdokumentet. Filtren ovan uppdaterar hela berättelsen.</p></section>'+kpis(rows,a.race,state.unit)+'<div class="grid analysis-flow"><section class="card chart-card"><div class="card-heading"><div><p class="eyebrow">MÅLGÅNGAR</p><h3>Sluttidsfördelning</h3></div>'+info('finish-method',methodText.finish)+'</div>'+sexHistogram(f,step)+'<p class="chart-caption">Fullföljda · n='+f.length+' · fasta '+step/60+'-minutersintervall'+(showSex?' · totalen visas bakom könsserierna':'')+'</p></section><section class="card percentile-card"><div class="card-heading"><div><p class="eyebrow">PERCENTILER</p><h3>När fältet når mål</h3></div>'+info('percentile-method','Percentilvärdena är beskrivande trösklar från fullföljda resultat. Antal visas per källstödd serie; inga måltider prognostiseras.')+'</div>'+progressionBySex(rows,showSex)+'</section>'+(showSex?'<section class="card gender-story"><div class="card-heading"><div><p class="eyebrow">KÖNSPERSPEKTIV</p><h3>Samma lopp, jämförbara serier</h3><p>Kvinnor och män visas separat när källans täckning räcker. Ett aktivt könsfilter ersätter uppdelningen med den valda gruppen.</p></div>'+info('gender-overview-method','Endast källstödda könsuppgifter används. Startande exkluderar DNS och okänd status. Saknat kön ligger kvar i totalen men förs aldrig över till kvinna/man-serierna.')+'</div>'+genderCards(rows)+'</section>':'')+classCard+'</div>'+groupSegmentComparison(a,rows,'class_name',a.race.participant.entity==='team'?'Lagklasser':'Klasser',state);
}
export function progression(f){if(!f.length)return empty('Inga fullföljare i urvalet.');return [10,25,50,75,90].map(p=>'<div class="progress-row"><span>'+p+' %'+(p===50?' · median':'')+'</span><div class="progress-track"><span style="width:'+p+'%"></span></div><strong>'+time(percentileValue(f.map(r=>r.finish_seconds),p))+'</strong></div>').join('')+'<p class="chart-caption">Median kräver n ≥ 5, 25/75 % n ≥ 10 och 10/90 % n ≥ 20. Ingen prognos.</p>';}
export function dynamics(a,rows,state){
 const sex=rows.filter(r=>r.sex==='F'||r.sex==='M'),age=rows.filter(r=>finite(r.age)),showSex=a.race.capabilities.sex_filter&&a.race.participant.entity==='person'&&!state.filters.sex&&rows.some(r=>r.sex==='F')&&rows.some(r=>r.sex==='M');
 const statusCard='<section class="card '+(a.race.capabilities.segment_analysis?'':'wide')+'"><div class="card-heading"><div><p class="eyebrow">UTFALL</p><h3>Status i urvalet</h3></div>'+info('status-method','Status kommer från källan. DNS räknas inte som start, DNF är startande som inte fullföljt och okänd status hålls utanför startantalet.')+'</div>'+table(['Status','Antal'],['FINISHED','DNF','DNS','DSQ','UNKNOWN'].map(status=>tr([esc(statusLabel(status)),rows.filter(r=>r.status===status).length])))+'<p class="chart-caption">DNS räknas inte som faktisk start. Okänd status hålls utanför startantalet.</p></section>';
 let html='<div class="grid">'+statusCard+(a.race.capabilities.segment_analysis?fieldFlow(a,rows,state):'')+'<section class="card wide finish-place-scatter"><div class="card-heading"><div><p class="eyebrow">PLACERING</p><h3>Sluttid mot totalplacering</h3></div><div class="heading-tools"><span class="badge">Klicka en punkt</span>'+info('placement-method','Varje punkt är ett fullföljt resultat med publicerad totalplacering. Klick eller Enter öppnar individuell analys. Kön färgkodas endast från källstödda uppgifter.')+'</div></div>'+finishPlaceScatter(rows.filter(finished))+'<p class="chart-caption">Varje punkt är ett publicerat fullföljt resultat med totalplacering. Serier kan tändas och släckas.</p></section>';
 if(showSex){html+='<section class="card gender-status-card"><div class="card-heading"><div><p class="eyebrow">KÖNSPERSPEKTIV</p><h3>Status och målgång per kön</h3></div>'+info('gender-status-method','Kvinnor och män jämförs bara när båda serierna finns i källan. Startande exkluderar DNS och okänd status; median kräver minst fem fullföljare.')+'</div>'+table(['Grupp','Startande','Fullföljde','DNF','DNS','Andel i mål','Median'],['F','M'].map(s=>{const g=sex.filter(r=>r.sex===s),starters=g.filter(r=>['FINISHED','DNF','DSQ'].includes(r.status)),done=g.filter(finished),rate=starters.length?100*done.length/starters.length:null;return tr(['<span class="sex-'+s+'">'+sexName(s)+'</span>',starters.length,done.length,g.filter(r=>r.status==='DNF').length,g.filter(r=>r.status==='DNS').length,finite(rate)?rate.toFixed(1).replace('.',',')+' %':'–',time(done.length>=5?quantile(done.map(r=>r.finish_seconds),.5):null)]);}))+'<p class="chart-caption">Könsuppgift infereras aldrig från namn.</p></section>';html+=genderDnfLocations(a,rows);}
 if(a.race.capabilities.segment_analysis)html+=strongestFinish(a,rows,state);
 if(a.race.capabilities.age_analysis){const ages=age.map(r=>r.age);html+='<section class="card age-analysis"><div class="card-heading"><div><p class="eyebrow">ÅLDER</p><h3>Ålder och åldersklasser</h3></div>'+info('age-method','Exakt ålder och publicerad åldersklass är separata källfält. Fördelningen använder endast exakt publicerad ålder; en åldersklass omvandlas aldrig till exakt ålder.')+'</div><div class="age-summary"><div><span>Median</span><strong>'+(age.length>=5?quantile(ages,.5):'–')+'</strong></div><div><span>Q25–Q75</span><strong>'+(age.length>=10?quantile(ages,.25).toFixed(0)+'–'+quantile(ages,.75).toFixed(0):'–')+'</strong></div></div>'+ageDistribution(age)+groupVisual(rows,'age_category',state.unit,a.race,'Åldersklasser',{limit:6})+'<p class="chart-caption">Exakt ålder finns för '+age.length+' av '+rows.length+' resultat i urvalet.</p></section>';}
 if(a.race.capabilities.club_analysis)html+='<section class="card club-analysis"><div class="card-heading"><div><p class="eyebrow">KLUBB & ORT</p><h3>Största grupperna</h3></div>'+info('club-method','Grupper baseras på publicerad klubb/ort. Skiftlägesvarianter samlas. Klicka en stapel för att filtrera hela analysen på gruppen.')+'</div>'+groupVisual(rows,'club',state.unit,a.race,'Klubb / ort',{filterable:true,limit:8})+'</section>'+groupSegmentComparison(a,rows,'club','Klubb / ort',state);
 return html+'</div>';
}

function dnfFunnel(a,rows,state){
 if(!a.race.capabilities.segment_analysis)return empty('Den här upplagan saknar publicerade mellantider för DNF-förlopp.');
 const dnf=rows.filter(r=>r.status==='DNF');if(!dnf.length)return empty('Inga DNF i aktuellt urval.');
 const groups=a.boundary.filter(cp=>cp.key!=='finish').map(cp=>({name:cp.name,count:dnf.filter(r=>a.passages(r).at(-1)?.checkpoint===cp.key).length})).filter(x=>x.count);
 const max=Math.max(1,...groups.map(x=>x.count));return '<div class="dnf-funnel">'+groups.map(x=>'<article><span>'+esc(x.name)+'</span><div><i style="width:'+(100*x.count/max).toFixed(1)+'%"></i></div><strong>'+x.count+'</strong></article>').join('')+'</div><p class="chart-caption">DNF grupperas efter senast observerade analyskontroll. Exakt brytplats infereras inte.</p>';
}
function segmentCharacter(a,rows,state){
 if(!a.race.capabilities.segment_analysis)return empty('Delsträckor saknas.');
 const stats=a.segmentStats(rows),valid=stats.filter(s=>finite(s.median));
 return valid.length?horizontalBars(valid.map(s=>({label:s.from.name+' → '+s.to.name,value:s.median})),{valueFormat:v=>pace(v,state.unit),maxRows:20}):empty('För få kompletta segment för stabil medianfart.');
}
function advancementRanking(a,rows){
 if(!a.race.capabilities.segment_analysis)return empty('Placeringsförändringar saknas.');
 const candidates=rows.filter(finished).map(r=>{const gains=a.boundary.slice(1).map((_,i)=>a.segment(r,i)?.gain).filter(finite),total=gains.reduce((sum,v)=>sum+v,0);return gains.length?{r,total}:null;}).filter(Boolean).filter(x=>x.total>0).sort((x,y)=>y.total-x.total).slice(0,10);
 return candidates.length?'<div class="ranking">'+candidates.map((x,i)=>'<button type="button" class="ranking-row" data-result="'+esc(x.r.source_result_id)+'"><b>'+(i+1)+'</b><span><strong>'+esc(x.r.name)+'</strong><small>#'+esc(x.r.bib)+' · '+esc(x.r.class_name||'')+'</small></span><em>+'+Math.round(x.total)+'</em></button>').join('')+'</div>':empty('Ingen källstödd positiv nettoförändring i urvalet.');
}
export function statistics(a,rows,state){
 return '<div class="analysis-grid gotaleden-statistics">'+
 '<section class="card wide finish-place-scatter"><div class="card-heading"><div><p class="eyebrow">PLACERINGSMOTOR</p><h3>Tid mot placering</h3></div>'+info('placement-method','Varje punkt är ett fullföljt resultat med publicerad totalplacering. Klick eller tangentbord öppnar individuell analys. Kön färgkodas endast från källstödda uppgifter.')+'</div>'+finishPlaceScatter(rows.filter(finished))+'</section>'+
 '<section class="card simulator"><div class="card-heading"><div><p class="eyebrow">MÅLTIDSSIMULATOR</p><h3>Vad krävs?</h3></div>'+info('target-time-method','Reglaget jämför vald sluttid med fullföljare i aktuellt filtrerat urval. Det är deskriptiv statistik, inte en prognos.')+'</div><div id="target-time-simulator" class="target-simulator"></div></section>'+
 '<section class="card"><div class="card-heading"><div><p class="eyebrow">REPET DRAS</p><h3>Avhopp genom loppet</h3></div>'+info('dnf-method','DNF placeras vid sista observerade analyskontroll. Saknad passage flyttas aldrig framåt.')+'</div>'+dnfFunnel(a,rows,state)+'</section>'+
 '<section class="card"><div class="card-heading"><div><p class="eyebrow">FARTSIGNATUR</p><h3>Delsträckornas karaktär</h3></div>'+info('segment-character-method','Medianfart per delsträcka beräknas från den kompletta, källstödda segmentkohorten.')+'</div>'+segmentCharacter(a,rows,state)+'</section>'+
 '<section class="card"><div class="card-heading"><div><p class="eyebrow">PLACERINGSEXPRESS</p><h3>Största avancemang</h3></div>'+info('advancement-method','Summerar endast publicerade placeringsförändringar mellan observerade analysgränser. Startplacering fabriceras inte.')+'</div>'+advancementRanking(a,rows)+'</section>'+
 '</div>';
}
function sexSeries(a,rows,state){
 const sexes=[['F','Kvinnor','#b51d60'],['M','Män','#2563eb']],labels=a.boundary.slice(1).map(cp=>cp.name);
 return {labels,series:sexes.map(([id,name,color])=>({id,name,color,stats:a.segmentStats(rows.filter(r=>r.sex===id))})).filter(s=>s.stats.some(x=>finite(x.median)))};
}
export function gender(a,rows,state){
 if(a.race.participant.entity==='team')return '<div class="card">'+groupVisual(rows,'class_name',state.unit,a.race,'Lagklasser',{limit:8})+'</div>'+groupSegmentComparison(a,rows,'class_name','Lagklasser',state);
 const known=rows.filter(r=>r.sex==='F'||r.sex==='M');if(!known.length)return empty('Källstödda könsuppgifter saknas för den här upplagan.');
 const ss=sexSeries(a,rows,state),paceChart=a.race.capabilities.segment_analysis&&ss.series.length?lines(ss.series.map(s=>({id:s.id,name:s.name,color:s.color,values:s.stats.map(x=>x.median)})),ss.labels,{format:v=>pace(v,state.unit)}):empty('Publicerade delsträckor saknas.');
 const retention=a.race.capabilities.segment_analysis&&ss.series.length?lines(ss.series.map(s=>({id:s.id,name:s.name,color:s.color,values:s.stats.map(x=>x.retention)})),ss.labels,{format:v=>Math.round(v),referenceValue:100}):empty('Fartretention saknas.');
 const doneF=known.filter(r=>r.sex==='F'&&finished(r)),doneM=known.filter(r=>r.sex==='M'&&finished(r)),medF=doneF.length>=5?quantile(doneF.map(r=>r.finish_seconds),.5):null,medM=doneM.length>=5?quantile(doneM.map(r=>r.finish_seconds),.5):null,items=[];
 if(finite(medF)&&finite(medM))items.push('<article><span>Median sluttid</span><strong>'+time(medF)+' / '+time(medM)+'</strong><small>Kvinnor / män · samma urval</small></article>');
 const startersF=known.filter(r=>r.sex==='F'&&['FINISHED','DNF','DSQ'].includes(r.status)),startersM=known.filter(r=>r.sex==='M'&&['FINISHED','DNF','DSQ'].includes(r.status));
 if(startersF.length&&startersM.length)items.push('<article><span>Fullföljande</span><strong>'+(100*doneF.length/startersF.length).toFixed(0)+' % / '+(100*doneM.length/startersM.length).toFixed(0)+' %</strong><small>Kvinnor / män</small></article>');
 return genderCards(rows)+'<div class="feature-grid equal-panels group-pace-comparison"><section class="card wide"><div class="card-heading"><div><p class="eyebrow">FART GENOM LOPPET</p><h3>Median & spridning per delsträcka</h3></div>'+info('gender-pace-method','Serierna använder endast källstödda könsuppgifter. Median kräver minst fem kompletta observationer; saknad passage blir lucka.')+'</div><div class="interactive-chart"><div class="series-controls"><label><input type="checkbox" data-series-toggle="F" checked><i class="female"></i>Kvinnor</label><label><input type="checkbox" data-series-toggle="M" checked><i class="male"></i>Män</label></div>'+paceChart+'</div></section><section class="card"><div class="card-heading"><div><p class="eyebrow">PACING</p><h3>Fartretention</h3></div>'+info('gender-retention-method','100 = respektive grupps egen hel-loppsbaslinje. Värdena beskriver gruppmedianen, inte individuell prestation.')+'</div>'+retention+'</section></div><section class="card automatic-insights"><div class="card-heading"><div><p class="eyebrow">AUTOMATISKA INSIKTER</p><h3>Vad skiljer grupperna?</h3></div></div><div class="story-strip">'+(items.length?items.join(''):empty('För litet källstött underlag för gruppinsikter.'))+'</div></section>';
}
const AGE_GROUPS=[{id:'under30',label:'<30',from:-Infinity,to:30},{id:'30-39',label:'30–39',from:30,to:40},{id:'40-49',label:'40–49',from:40,to:50},{id:'50-59',label:'50–59',from:50,to:60},{id:'60plus',label:'60+',from:60,to:Infinity}];
export function ageAnalysis(a,rows,state){
 const colors=['#1677a8','#8fbe63','#d9a441','#b51d60','#7651a0','#497b35','#92691a'];
 const makeGroup=(id,label,all,index)=>{const starters=all.filter(r=>['FINISHED','DNF','DSQ'].includes(r.status)),finishers=all.filter(finished);return {id,label,index,all,starters,finishers,stats:a.race.capabilities.segment_analysis?a.segmentStats(all):[]};};
 let available,team=a.race.participant.entity==='team';
 if(team){
  const names=[...new Set(rows.map(r=>String(r.class_name||'').trim()).filter(Boolean))].sort((x,y)=>x.localeCompare(y,'sv',{numeric:true}));
  available=names.map((name,index)=>makeGroup('class-'+index,name,rows.filter(r=>r.class_name===name),index)).filter(g=>g.all.length>=5);
 }else{
  available=AGE_GROUPS.map((g,index)=>makeGroup(g.id,g.label,rows.filter(r=>finite(r.age)&&Number(r.age)>=g.from&&Number(r.age)<g.to),index)).filter(g=>g.all.length>=5);
 }
 if(!available.length)return empty(team?'För få lag i publicerade klasser för klassanalys.':'För få resultat med exakt publicerad ålder för Gotaledens åldersgrupper.');
 const validIds=new Set(available.map(g=>g.id)),requested=(state.ageGroups||[]).filter(id=>validIds.has(id));if(!requested.length)requested.push(...available.slice(0,5).map(g=>g.id));state.ageGroups=requested.slice(0,5);
 const selected=available.filter(g=>state.ageGroups.includes(g.id)),labels=a.boundary.slice(1).map(cp=>cp.name),colorOf=g=>colors[g.index%colors.length],stat=state.ageHeatStat==='fastest10'?'fastest10':'median';
 const paceChart=a.race.capabilities.segment_analysis?lines(selected.map(g=>({id:g.id,name:g.label,color:colorOf(g),values:g.stats.map(x=>x.median)})),labels,{format:v=>pace(v,state.unit)}):empty('Delsträckor saknas.');
 const summaryHtml='<div class="age-summary-list">'+selected.map(g=>'<article style="--age-color:'+colorOf(g)+'"><span>'+esc(g.label)+'</span><strong>'+g.all.length+'</strong><small>'+(g.starters.length?Math.round(100*g.finishers.length/g.starters.length):0)+' % fullföljde · median '+time(g.finishers.length>=5?quantile(g.finishers.map(r=>r.finish_seconds),.5):null)+'</small></article>').join('')+'</div>';
 const summarize=(g,i)=>{const values=g.all.map(r=>a.segment(r,i)?.pace).filter(v=>finite(v)&&v>0).sort((x,y)=>x-y);if(!values.length)return {value:null,count:0,total:0};if(stat==='fastest10'){const count=Math.max(1,Math.ceil(values.length*.1)),pick=values.slice(0,count);return {value:pick.reduce((s,v)=>s+v,0)/count,count,total:values.length};}return {value:values.length>=5?quantile(values,.5):null,count:values.length,total:values.length};};
 const heat=selected.map(g=>({g,cells:labels.map((_,i)=>summarize(g,i))})),allValues=heat.flatMap(row=>row.cells.map(x=>x.value).filter(finite)),min=allValues.length?Math.min(...allValues):0,max=allValues.length?Math.max(...allValues):1;
 const cell=x=>{if(!finite(x.value))return '<span class="heat-empty">–</span>';const ratio=(x.value-min)/(max-min||1),light=92-ratio*42,display=pace(x.value,state.unit);return '<span style="background:hsl('+(165-ratio*120)+' 48% '+light+'%)" title="'+esc(display+' · '+x.count+' av '+x.total+' giltiga')+'">'+esc(display.replace(' min/km','').replace(' km/h',''))+'</span>';};
 const heatmap=a.race.capabilities.segment_analysis?'<div class="heatmap-grid" style="--heat-cols:'+(labels.length+1)+'"><b>'+(team?'Klass':'Grupp')+'</b>'+labels.map(label=>'<b>'+esc(label)+'</b>').join('')+heat.map(row=>'<strong>'+esc(row.g.label)+'</strong>'+row.cells.map(cell).join('')).join('')+'</div>':empty('Delsträckor saknas.');
 const controls='<div class="age-group-controls">'+available.map(g=>'<button type="button" data-age-group="'+esc(g.id)+'" aria-pressed="'+state.ageGroups.includes(g.id)+'" style="--age-color:'+colorOf(g)+'">'+esc(g.label)+' <small>'+g.all.length+'</small></button>').join('')+'</div>';
 const title=team?'Klassanalys':'Ålderslabbet',eyebrow=team?'OFFICIELLA KLASSER':'KLASS & ÅLDER',copy=team?'Jämförelsen använder endast publicerade lagklasser. Ingen medlem kopplas till etapp eller individuell ålder.':'Analytiska åldersgrupper – inte officiella tävlingsklasser. Grupperna visas alltid i åldersordning.';
 const retention=team&&a.race.capabilities.segment_analysis?'<section class="card"><div class="card-heading"><div><p class="eyebrow">KLASSVIS PACING</p><h3>Fartretention per klass</h3></div><span class="badge">100 = respektive klass egen hel-loppsmedianfart</span></div>'+lines(selected.map(g=>({id:g.id,name:g.label,color:colorOf(g),values:g.stats.map(x=>x.retention)})),labels,{format:v=>String(Math.round(v)),referenceValue:100})+'</section>':'';
 return '<div class="age-analysis-head"><p class="eyebrow">'+eyebrow+'</p><h3>'+title+'</h3><p>'+copy+'</p></div>'+controls+'<div class="feature-grid"><section class="card wide"><div class="card-heading"><div><p class="eyebrow">ÅLDERSGRUPPER</p><h3>Medianfart genom loppet</h3></div>'+info('age-pace-method',team?'Valda publicerade klasser jämförs med var sin kompletta segmentkohort.':'Åldersgrupperna är fasta och sorteras i åldersordning: <30, 30–39, 40–49, 50–59, 60+. De sorteras aldrig efter deltagarantal.')+'</div>'+paceChart+'</section><section class="card"><div class="card-heading"><div><p class="eyebrow">UNDERLAG</p><h3>Deltagande och målgång</h3></div></div>'+summaryHtml+'</section></div>'+retention+'<section class="card"><div class="card-heading"><div><p class="eyebrow">FARTKARTA</p><h3>Analysgrupp × delsträcka</h3></div><div class="age-heatmap-tools"><div class="age-heatmap-stat" role="group" aria-label="Välj statistik i fartkartan"><button type="button" data-age-heat-stat="median" aria-pressed="'+(stat==='median')+'">Median</button><button type="button" data-age-heat-stat="fastest10" aria-pressed="'+(stat==='fastest10')+'">Snabbaste 10 %</button></div><span class="badge">'+(stat==='fastest10'?'Snabbaste 10 %':'Median')+' · '+(state.unit==='speed'?'km/h':'min/km')+'</span></div></div>'+heatmap+'</section>';
}

export function clubs(a,rows,state){
 if(!a.race.capabilities.club_analysis)return empty('Klubb- eller ortsuppgifter saknas.');
 return '<section class="card club-arena"><div class="card-heading"><div><p class="eyebrow">KLUBB- OCH ORTSARENAN</p><h3>Gemenskap i siffror</h3></div>'+info('club-arena-method','Grupper baseras på publicerad klubb/ort. Klick på en stapel filtrerar den aktuella analysen; personprofilen påverkas inte av fältfiltret.')+'</div>'+groupVisual(rows,'club',state.unit,a.race,'Klubb / ort',{filterable:true,limit:12})+'</section>'+groupSegmentComparison(a,rows,'club','Klubb / ort',state);
}

export function segments(a,rows,state){
 if(!a.race.capabilities.segment_analysis)return empty('Detta lopp hade inga publicerade mellantider. Resultat- och målgångsanalys finns fortfarande.');
 const stats=a.segmentStats(rows),chosen=stats[state.segment]||stats[0],hasPace=stats.length>0&&stats.every(s=>finite(s.median));
 const showSex=a.race.capabilities.sex_filter&&a.race.participant.entity==='person'&&!state.filters.sex&&rows.some(r=>r.sex==='F')&&rows.some(r=>r.sex==='M'),female=showSex?a.segmentStats(rows.filter(r=>r.sex==='F')):[],male=showSex?a.segmentStats(rows.filter(r=>r.sex==='M')):[],sexValue=x=>finite(x?.median)?pace(x.median,state.unit):time(x?.time?.median),spread=(s,lo,hi)=>hasPace&&finite(s?.[lo])?pace(s[lo],state.unit)+' – '+pace(s[hi],state.unit):finite(s?.time?.[lo])?time(s.time[lo])+' – '+time(s.time[hi]):'–';
 const main='<section class="card"><div class="card-heading"><div><h3>Delsträckor · tid, fart och spridning</h3></div>'+info('segment-method',methodText.segment)+'</div>'+bands(hasPace?stats:stats.map(s=>({...s,...s.time})),hasPace?state.unit:'time')+'<p class="chart-caption">'+(hasPace?'Fart':'Tid (distans saknas för fartberäkning)')+' · Punkt: median · band: Q25–Q75 · linje: Q10–Q90 · samma kompletta kohort n='+(stats[0]?.complete??0)+'.</p><div class="segment-buttons">'+stats.map((s,i)=>'<button data-segment="'+i+'" aria-pressed="'+(state.segment===i)+'">'+(i+1)+'. '+esc(s.to.name)+'</button>').join('')+'</div>'+table(['Segment','Distans¹','Mediantid','Medianfart','Q25–Q75','Q10–Q90','Fartretention²','Plats ±','DNF³','n'],stats.map((s,i)=>tr([esc(s.from.name+' → '+s.to.name),finite(s.to.race_distance_km)&&finite(s.from.race_distance_km)?(s.to.race_distance_km-s.from.race_distance_km).toFixed(1)+' km':'–',time(s.time.median),pace(s.median,state.unit),spread(s,'q25','q75'),spread(s,'q10','q90'),finite(s.retention)?s.retention.toFixed(0)+' %':'–',finite(s.gain)?(s.gain>0?'+':'')+s.gain:'–',s.dnf,s.time.n+(s.time.n<10?' · Litet underlag':'')])) )+'<p class="chart-caption">¹ Rapporterad distans. ² 100 % = individens egen genomsnittsfart för hela loppet; därefter median för kohorten. ³ Sista observerade analysgräns för DNF, inte bevisad brytplats.</p></section>';
 const gender=showSex?'<section class="card gender-segments interactive-chart"><div class="card-heading"><div><p class="eyebrow">KÖNSSERIER</p><h3>Median per delsträcka</h3></div>'+info('segment-sex-method','Kvinnor och män beräknas separat från källstödda könsuppgifter. Median visas först vid minst fem kompletta observationer i respektive grupp.')+'</div><div class="series-controls" aria-label="Visa delsträckor per kön"><label><input type="checkbox" data-series-toggle="female" checked> <i class="female"></i>Kvinnor</label><label><input type="checkbox" data-series-toggle="male" checked> <i class="male"></i>Män</label></div><div class="gender-segment-grid"><div data-series="female"><h4><span class="sex-F">Kvinnor</span></h4>'+table(['Delsträcka','Median','n'],stats.map((s,i)=>tr([esc(s.from.name+' → '+s.to.name),sexValue(female[i]),female[i]?.time.n??0])))+'</div><div data-series="male"><h4><span class="sex-M">Män</span></h4>'+table(['Delsträcka','Median','n'],stats.map((s,i)=>tr([esc(s.from.name+' → '+s.to.name),sexValue(male[i]),male[i]?.time.n??0])))+'</div></div></section>':'';
 const detail=chosen?'<section class="card selected-detail"><div class="card-heading"><h3>'+esc(chosen.from.name+' → '+chosen.to.name)+'</h3>'+info('selected-segment-method','Detaljen följer vald delsträcka ovan. Underlaget är samma kompletta kohort som i segmentanalysen; saknade passager fylls aldrig ut.')+'</div><p>'+chosen.time.n+' kompletta observationer. Mediantid '+time(chosen.time.median)+(hasPace?' · medianfart '+pace(chosen.median,state.unit):'')+'.</p><p class="muted">Stigning och höjd visas i banvyn när aktuell GPX har höjddata. Ingen sammanvägd svårighetspoäng används.</p></section>':'';
 return main+gender+detail;
}
export function course(a){
 const c=a.course,assets=c?.assets;
 const geometryDistance=c&&finite(c.geometry_evidence?.derived_path_distance_km)?'<p class="muted">Geometrisk referens: '+esc(c.geometry_evidence.derived_path_distance_km)+' km. Detta är inte automatiskt tävlingsdagens exakta distans.</p>':'';
 return '<section class="card"><div class="card-heading"><h3>Banans underlag</h3>'+info('course-method','Banversion, geometri och rutt behandlas separat. En verifierad banversion betyder inte automatiskt att en lokal GPX får publiceras eller att en annan upplagas rutt kan lånas.')+'</div>'+ (c?'<p><span class="badge '+(!assets?.official_gpx?'reference':'')+'">'+(assets?.official_gpx?'Arrangörs-GPX':assets?.route?'Rekonstruerad bana':c.geometry_evidence.status.startsWith('provisional')?'Arbetsreferens · rekonstruktion':'Verifierad geometri · ingen lokal rutt')+'</span></p><p>Banversion: <strong>'+esc(c.course_version)+'</strong></p>'+geometryDistance:empty('Banversionen är inte verifierad för denna upplaga. Årsspecifik proveniens saknas; historisk prestationsjämförelse är därför avstängd.'))+(c?.geometry_evidence.status.startsWith('provisional')?'<p>13,472 km arbetsreferens via Hallamölla. Varken officiell GPX eller godkänd lokal rutt. Ingen replay.</p>':'')+'<p>Markeringen på tävlingsdagen gäller framför GPX. En verifierad banversion innebär inte automatiskt rätt att publicera geometrin.</p>'+ (assets?.route?'<button id="load-course">Visa karta och höjdprofil</button><div class="segment-buttons">'+(a.race.capabilities.segment_analysis?a.boundary.slice(1).map((c,i)=>'<button data-segment="'+i+'" aria-pressed="false">'+esc(c.name)+'</button>').join(''):'')+'</div><div id="course-map"></div>':empty('Lokalt användbar rutt saknas för denna upplaga. Ingen annan upplagas bana lånas.'))+'</section>';
}
export function profile(a,r,state,saved){
 const f=a.records.filter(finished),faster=finished(r)&&f.length>1?100*f.filter(x=>x.finish_seconds>r.finish_seconds).length/(f.length-1):null;
 let html='<section class="profile-hero"><div><p class="eyebrow">'+(a.race.participant.entity==='team'?'LAGPROFIL':'LÖPARPROFIL')+' · '+a.race.year+'</p><h2 id="profile-title">'+esc(r.name)+'</h2><div class="profile-meta"><span>#'+esc(r.bib)+'</span><span>'+esc(r.class_name||'Klass saknas')+'</span><span>'+esc(r.club||'Klubb / ort saknas')+'</span><span>'+esc(statusLabel(r.status))+'</span></div></div><div class="profile-finish"><small>Sluttid</small><strong>'+time(finished(r)?r.finish_seconds:null)+'</strong><span>'+(r.overall_place?'Plats '+r.overall_place:'Publicerat resultat')+(finished(r)&&finite(a.race.nominal_distance_km)?' · '+pace(r.finish_seconds/a.race.nominal_distance_km,state.unit):'')+'</span></div></section>';
 html+='<nav class="profile-quick-nav" aria-label="Profilnavigation"><button type="button" data-profile-jump="profile-summary">Sammanfattning</button>'+(a.race.capabilities.replay?'<button type="button" data-profile-jump="profile-replay">Replay</button>':'')+(a.race.capabilities.segment_analysis?'<button type="button" data-profile-jump="profile-journey">Loppets utveckling</button><button type="button" data-profile-jump="profile-splits">Mellantider</button>':'')+'</nav>';
 if(a.race.capabilities.replay)html+='<section class="profile-replay-shell" aria-labelledby="profile-replay-title"><div class="card-heading"><div><p class="eyebrow">INTERAKTIV LOPPREPLAY</p><h3 id="profile-replay-title">Karta, fart och passager</h3></div>'+info('profile-replay-method','Replay interpolerar position mellan verkliga publicerade passager längs den lokalt tillgängliga rutten. Den är en presentation av timingdata, inte deltagarens GPS-spår.')+'</div><div id="profile-replay">'+empty('Laddar karta, jämförelser och Replay…')+'</div></section>';
 else if(a.race.capabilities.segment_analysis)html+=empty('Replay kräver publicerade passager och en lokalt användbar rutt. Ruttunderlag saknas för denna upplaga.');
 html+='<div class="kpis" id="profile-summary">'+[['Sluttid',finished(r)?time(r.finish_seconds):'–'],['Totalplats',r.overall_place??'–'],['Klassplats',r.class_place??'–'],['Snabbare än',finite(faster)?faster.toFixed(1)+' %':'–']].map(([k,v])=>'<div class="kpi"><span>'+k+'</span><strong>'+v+'</strong></div>').join('')+'</div><div class="toolbar"><button data-favorite="'+esc(r.source_result_id)+'" aria-pressed="'+saved+'">'+(saved?'Sparad':'Spara lopp')+'</button><button data-add-compare="'+esc(r.source_result_id)+'" data-open-compare-after="true">Jämför detta resultat</button></div><p class="muted">Jämförelse mot övriga fullföljare i samma upplaga, n='+f.length+'. Fältfiltren begränsar inte profilen.</p>';
 if(a.race.participant.entity==='team')html+='<section class="card"><h3>Publicerade lagmedlemmar</h3>'+table(['Källordning','Namn','Publicerad tid'],a.members(r).map(m=>tr([m.source_sequence,esc(m.name_as_published),time(m.member_time_seconds)])))+'<p class="muted">Källans ordning är bevarad. Medlem till etapp är inte verifierad. Analysen avser lagets passager.</p></section>';
 else html+='<p>Kön: '+esc(r.sex==='F'?'Kvinna':r.sex==='M'?'Man':'–')+' · Exakt ålder: '+esc(r.age??'–')+' · Åldersklass: '+esc(r.age_category??'–')+' · Land: '+esc(r.country||'–')+'</p>';
 if(a.race.capabilities.segment_analysis)html+='<section class="card" id="profile-journey"><div class="card-heading"><h3>Din resa · publicerade passager</h3>'+info('profile-journey-method','Endast publicerade passager kopplas till deltagarens Journey. Saknad passage fylls inte ut och tid mellan två observationer tolkas inte som depåtid.')+'</div>'+table(['Kontroll','Tid','Plats','Underlag'],a.checkpoints.map(c=>{const o=a.observation(r,c.key);return tr([esc(c.source_label||c.name),time(o?.elapsed_seconds),o?.place_overall??'–',o?(o.calculated?'Beräknat startankare':o.from_result?'Källvärde · resultat':'Källvärde'):'Passage saknas']);}))+'<p class="muted">Extra källobservationer behålls separat. Tid mellan observationer är inte bevisad depåtid.</p></section>';
 if(a.race.capabilities.segment_analysis){const field=a.segmentStats(a.records);html+='<section class="card" id="profile-splits"><div class="card-heading"><h3>Dina delsträckor & placeringsresa</h3>'+info('profile-segments-method','Deltagarens observerade delsträckor jämförs med hela upplagans kompletta fullföljarkohort. Fältmedian kräver minst fem observationer; saknade passager eller placeringar fylls aldrig ut.')+'</div>'+table(['Delsträcka','Din tid','Din fart','Fältmedian tid','Mot fältmedian','Plats ±'],a.boundary.slice(1).map((c,i)=>{const s=a.segment(r,i),medianTime=field[i]?.time?.median,delta=s&&finite(medianTime)?s.seconds-medianTime:null;return tr([esc(c.name),time(s?.seconds),pace(s?.pace,state.unit),time(medianTime),finite(delta)?time(delta):'–',finite(s?.gain)?(s.gain>0?'+':'')+s.gain:'–']);}))+'<p class="muted">Fältmedianen avser hela den valda upplagans kompletta fullföljarkohort och visas först vid n ≥ 5. Negativ skillnad mot median = snabbare delsträcka. Positiv plats ± = vunna placeringar. Saknad passage eller placering fylls aldrig ut.</p></section>';}
 return html+'<p class="muted">Ingen personhistorik över år: verifierad identitetskoppling saknas.</p>';
}
export function compare(a,state){
 const selected=state.compare.map(id=>a.byId.get(id)).filter(Boolean);
 const compareCopy=a.race.capabilities.replay?'Sök i hela den valda upplagan och välj 2 för Direktjämförelse eller 2–5 för Kartduell.':'Sök i hela den valda upplagan och välj exakt 2 för Direktjämförelse. Kartduell kräver verifierad lokal rutt och verkliga mellantider.';
 const limit=a.race.capabilities.replay?5:2;
 let h='<section class="card compare-picker"><div><p class="eyebrow">INDIVIDUELL JÄMFÖRELSE</p><h3>Välj löpare eller lag</h3><p>'+compareCopy+'</p><div class="compare-selection-meta"><strong>'+selected.length+' / '+limit+'</strong><span>valda</span>'+(selected.length?'<button type="button" data-clear-compare>Rensa val</button>':'')+'</div></div><div class="compare-search-wrap"><label>Sök resultat<input id="compare-search" type="search" autocomplete="off" role="combobox" aria-autocomplete="list" aria-controls="compare-options" aria-expanded="false" placeholder="Skriv namn eller startnummer"></label><div id="compare-options" class="suggestions" role="listbox" hidden></div></div><div class="comparison-list">'+(selected.length?selected.map((r,i)=>'<button data-remove-compare="'+esc(r.source_result_id)+'"><i>'+(i+1)+'</i>'+esc(r.name)+' <span>×</span></button>').join(''):'<span class="selection-empty">Inga löpare eller lag valda ännu.</span>')+'</div></section>';
 if(selected.length===2){
  const [x,y]=selected;
  const gap=finished(x)&&finished(y)?y.finish_seconds-x.finish_seconds:null;
  h+='<section class="card head-to-head"><div class="compare-title"><div><p class="eyebrow">DIREKTJÄMFÖRELSE</p><h3>Två resultat, sida vid sida</h3></div><div class="heading-tools"><span class="badge">Samma upplaga</span>'+info('head-to-head-method','Jämförelsen använder två publicerade resultat från samma RaceEdition. Passager och delsträckor visas bara när båda har källstöd; saknade observationer beräknas inte från replay.')+'</div></div><div class="versus"><article class="runner-one"><span>01</span><h3>'+esc(x.name)+'</h3><p>#'+esc(x.bib)+' · '+esc(x.class_name||'Klass saknas')+'</p><strong>'+time(x.finish_seconds)+'</strong></article><div class="gap-card"><small>Sluttidsskillnad</small><strong>'+time(finite(gap)?Math.abs(gap):null)+'</strong><span>'+(finite(gap)?(gap<0?esc(y.name):esc(x.name))+' före':'Ej jämförbart')+'</span></div><article class="runner-two"><span>02</span><h3>'+esc(y.name)+'</h3><p>#'+esc(y.bib)+' · '+esc(y.class_name||'Klass saknas')+'</p><strong>'+time(y.finish_seconds)+'</strong></article></div>';
  if(a.race.capabilities.head_to_head)h+='<div class="compare-tables"><div><h3>Passager</h3>'+table(['Kontroll',esc(x.name),esc(y.name),'Skillnad 02 − 01'],a.checkpoints.filter(c=>c.key!=='start').map(c=>{const p=a.observation(x,c.key),q=a.observation(y,c.key),metric=o=>'<span class="comparison-metric"><strong>'+time(o?.elapsed_seconds)+'</strong><small>plats '+(o?.place_overall??'–')+'</small></span>';return tr([esc(c.name),metric(p),metric(q),'<strong class="gap-value">'+(p&&q?time(q.elapsed_seconds-p.elapsed_seconds):'–')+'</strong>']);}))+'</div><div><h3>Delsträckor</h3>'+table(['Till',esc(x.name),esc(y.name),'Delsträcksskillnad'],a.boundary.slice(1).map((c,i)=>{const p=a.segment(x,i),q=a.segment(y,i),metric=s=>'<span class="comparison-metric"><strong>'+time(s?.seconds)+'</strong><small>'+pace(s?.pace,state.unit)+' · plats '+(finite(s?.gain)?(s.gain>0?'+':'')+s.gain:'–')+'</small></span>';return tr([esc(c.name),metric(p),metric(q),'<strong class="gap-value">'+(p&&q?time(q.seconds-p.seconds):'–')+'</strong>']);}))+'</div></div>';
  const shared=a.checkpoints.filter(c=>c.key!=='start').map(c=>{const p=a.observation(x,c.key),q=a.observation(y,c.key);return p&&q?{name:c.name,gap:q.elapsed_seconds-p.elapsed_seconds}:null;}).filter(Boolean),signed=shared.filter(p=>p.gap!==0),leadChanges=signed.reduce((n,p,i)=>i&&Math.sign(p.gap)!==Math.sign(signed[i-1].gap)?n+1:n,0),largest=shared.slice().sort((p,q)=>Math.abs(q.gap)-Math.abs(p.gap))[0],nearest=shared.slice().sort((p,q)=>Math.abs(p.gap)-Math.abs(q.gap))[0];
  if(shared.length)h+='<div class="duel-insights"><article><span>Gemensamma passager</span><strong>'+shared.length+'</strong><small>verkliga observationer</small></article><article><span>Ledningsväxlingar</span><strong>'+leadChanges+'</strong><small>mellan observerade passager</small></article><article><span>Största observerade lucka</span><strong>'+time(Math.abs(largest.gap))+'</strong><small>'+esc(largest.name)+' · '+esc(largest.gap>0?x.name:largest.gap<0?y.name:'Lika')+' före</small></article><article><span>Närmast varandra</span><strong>'+time(Math.abs(nearest.gap))+'</strong><small>'+esc(nearest.name)+'</small></article></div>';
  h+='<p class="comparison-note">Negativ skillnad betyder att resultat 02 var snabbare. Saknad passage lämnas tom och beräknas aldrig.</p></section>';
 }
 if(selected.length>=2&&a.race.capabilities.replay)h+='<button class="primary" id="open-duel">Öppna Kartduell ('+selected.length+')</button>';
 else if(!a.race.capabilities.replay)h+=empty('Kartduell är inte tillgänglig för denna upplaga: verifierad lokal rutt och verkliga mellantider krävs.');
 return h;
}
export function historyView(a,doc,boot,state=null){
 const entries=doc.editions.filter(e=>e.race_family===a.race.race_family),years=[...new Set([...entries.map(e=>e.year),...boot.cancelled_years])].sort((x,y)=>x-y);
 const hasSex=entries.some(e=>e.starter_sex_coverage);
 const tableHtml='<section class="card wide"><h3>Deltagande och prestation</h3>'+info('history-method',methodText.history)+table(['År','Resultat','Startande','Fullföljde','DNF',...(hasSex?['Kvinnor start','Män start','Könstäckning start']:[]),'Median¹','Bästa tid¹','Jämförbarhet'],years.map(year=>{if(boot.cancelled_years.includes(year))return tr([year,'Inställt','–','–','–',...(hasSex?['–','–','–']:[]),'–','–','Ingen datapunkt']);const e=entries.find(r=>r.year===year),allowed=comparable(a.race,e,boot.courses),sexKnown=e.starter_sex_coverage>0;return tr([year,e.records,e.starters??'–',e.finished,e.dnf,...(hasSex?[sexKnown?e.women_starters:'–',sexKnown?e.men_starters:'–',e.starter_sex_coverage+'/'+e.starters]:[]),allowed?time(e.median):'–',allowed?time(e.best):'–',allowed?'Jämförbar med vald upplaga':'Separat / ej verifierad serie']);}))+'<p class="chart-caption">¹ Endast jämförbart med vald upplaga. 2020–2021 var inställda. Könsuppdelningen avser faktiska startande med källstödd könsuppgift.</p></section>';
 return '<div class="grid history-intelligence">'+historyFingerprint(a,entries,boot)+historyRecord(a,entries,boot)+historySex(entries)+tableHtml+'</div>';
}
export function methodology(a,boot,state,rows=[]){
 return methodGuide(a,rows,state,boot)+'<section class="card"><h3>Källor, beräkningar och gränser</h3><p>Valt lopp: '+esc(a.race.section)+' '+a.race.year+'. Laddad omfattning: vald upplaga och en liten historiksammanställning; rutt, höjd och replay laddas först när de används.</p>'+Object.entries(methodText).map(([key,text])=>'<details><summary>'+({finish:'Sluttider och urval',segment:'Delsträckor och litet underlag',history:'Historisk jämförbarhet',replay:'Karta och replay'}[key])+'</summary><p>'+esc(text)+'</p></details>').join('')+'<details><summary>Demografi, Duo och identitet</summary><p>Kön och ålder visas endast när källan stöder uppgiften. En åldersklass är aldrig exakt ålder. Lagklass kommer från källan och härleds inte från medlemmar. fältet source_sequence är källans publiceringsordning, inte etappnummer. Favoriter lagras lokalt som resultat-ID. Ingen personidentitet skapas.</p></details><p>Källlager: Sportstiming, kuraterat fryst arkiv 2018–2026. 34 genomförda upplagor, 9 871 resultat och 6 123 observerade mellantidspassager.</p><p>Engine 1.0 · datageneration <code>'+esc(boot.payload_sha256.slice(0,16))+'</code></p><p><a href="https://www.sportstiming.dk/">Sportstiming</a> · <a href="https://www.osterlentrail.se/">Arrangören</a></p></section>';
}
